function renderReference(){
 const search=$("referenceSearch");if(!search)return;const q=search.value.trim().toLowerCase();
 const tenseEntries=tenses.map(t=>({category:t.time,name:t.name,form:t.form,negative:t.negative,question:t.question,example:t.example,note:t.meaning+" "+t.insight+" "+t.extra,check:referenceChecks[t.name].q,options:referenceChecks[t.name].o,correct:referenceChecks[t.name].a,why:referenceChecks[t.name].e}));
 const all=[...tenseEntries,...referenceExtras.map(x=>({...x,group:"Grammar tools"}))];const filtered=all.filter(x=>(activeReferenceFilter==="All"||(activeReferenceFilter==="Grammar tools"?x.group==="Grammar tools":x.category===activeReferenceFilter))&&(x.name+" "+x.category+" "+x.form+" "+x.negative+" "+x.question+" "+x.example+" "+x.note).toLowerCase().includes(q));
 $("referenceCount").textContent=`${filtered.length} ${filtered.length===1?"topic":"topics"}`;
 $("referenceList").innerHTML=filtered.length?filtered.map((x,i)=>`<details class="reference-card"><summary><span class="ref-label">${x.category}</span><h3>${x.name}</h3><span class="ref-open">Explore topic <b>＋</b></span></summary><div class="ref-content"><div class="reference-row"><strong>Structure / form</strong><span>${x.form}</span></div><div class="reference-row"><strong>Negative</strong><span>${x.negative}</span></div><div class="reference-row"><strong>Question</strong><span>${x.question}</span></div><div class="ref-example"><strong>Example:</strong> ${x.example}</div><p class="note">${x.note}</p><div class="ref-quickcheck"><strong>Quick check</strong><p>${x.check}</p><div class="ref-check-options">${x.options.map((o,j)=>`<label><input type="radio" name="refcheck${i}" value="${j}"> ${o}</label>`).join("")}</div><button class="btn secondary ref-check-submit" type="button">Check answer</button><p class="ref-answer hidden" aria-live="polite"></p></div></div></details>`).join(""):`<div class="empty-state">No matching reference entries. Try a different search term or filter.</div>`;
 document.querySelectorAll(".ref-check-submit").forEach((b,i)=>b.onclick=()=>{const card=b.closest(".ref-quickcheck"),picked=card.querySelector("input:checked"),item=filtered[i],answer=card.querySelector(".ref-answer");answer.classList.remove("hidden");if(!picked){answer.textContent="Choose an answer first.";return;}const correct=Number(picked.value)===item.correct;answer.innerHTML=`<strong>${correct?"Correct!":"Not quite."}</strong> ${item.why}${correct?"":" Correct answer: "+item.options[item.correct]+"."}`;});
}
const referenceChecks={
"Present Simple":{q:"Which sentence describes a regular routine?",o:["She is taking the bus today.","She takes the bus every morning.","She has taken the bus."],a:1,e:"The sentence describes a repeated routine, so Present Simple fits."},
"Present Continuous":{q:"Which sentence describes a temporary situation around now?",o:["I work in Davao permanently.","I am staying with my cousin this week.","I stayed there last week."],a:1,e:"This week marks a temporary situation around the present."},
"Present Perfect":{q:"Which sentence focuses on experience up to now?",o:["I visited Seoul in 2022.","I have visited Seoul twice.","I was visiting Seoul."],a:1,e:"Present Perfect presents experience within the time up to now, without a finished past-time reference."},
"Present Perfect Continuous":{q:"Which sentence emphasizes an activity continuing until now?",o:["She has been studying for three hours.","She studied yesterday.","She studies every day."],a:0,e:"The form highlights the ongoing activity and its duration up to now."},
"Past Simple":{q:"Which sentence uses a finished past-time reference?",o:["I have seen him recently.","I saw him last Friday.","I am seeing him now."],a:1,e:"Last Friday is a finished past-time reference; Past Simple is appropriate."},
"Past Continuous":{q:"Which sentence places an activity in progress at a past moment?",o:["At nine, I was driving home.","I drive home at nine.","I have driven home."],a:0,e:"Was driving views the activity as in progress at a particular past time."},
"Past Perfect":{q:"Which sentence clearly places one event before a later past point?",o:["The train had left before we arrived.","The train leaves at six.","The train has left now."],a:0,e:"Had left places the departure before the later past reference point, our arrival."},
"Past Perfect Continuous":{q:"Which sentence emphasizes duration before a past reference point?",o:["They had been waiting for an hour when the bus came.","They wait every day.","They have waited today."],a:0,e:"Had been waiting highlights the activity and its duration leading up to the bus's arrival."},
"Future Simple (will)":{q:"Which sentence expresses a spontaneous decision?",o:["Look at those clouds; it is going to rain.","The phone is ringing. I'll answer it.","The train leaves at six."],a:1,e:"I'll answer it is a decision made at the moment of speaking."},
"Future Continuous":{q:"Which sentence views an activity as in progress at a future time?",o:["At ten tomorrow, I'll be presenting.","I presented yesterday.","I have presented already."],a:0,e:"Will be presenting places the activity in progress at a future reference time."},
"Future Perfect":{q:"Which sentence focuses on completion before a future deadline?",o:["By Friday, we will have finished the report.","We are finishing the report now.","We finished it yesterday."],a:0,e:"Will have finished presents completion before the future point, Friday."},
"Future Perfect Continuous":{q:"Which sentence emphasizes duration up to a future point?",o:["By June, she will have been teaching for ten years.","She teaches every day.","She will teach tomorrow."],a:0,e:"Will have been teaching highlights the length of the activity up to June."}
};

