function renderTense(name){
 const t=tenses.find(x=>x.name===name);if(!t)return;
 document.querySelectorAll(".tense-pick").forEach(b=>b.classList.toggle("active",b.dataset.tense===name));
 const panel=$("tenseDetail");panel.classList.remove("hidden");panel.setAttribute("aria-hidden","false");
 panel.innerHTML=`<div class="tense-detail-top"><button type="button" class="back-to-forms" id="backToForms">← All ${t.time.toLowerCase()} forms</button><span class="pill">${t.time.toUpperCase()} · ${t.name.split(" ").slice(1).join(" ").toUpperCase()}</span></div>
 <h3>${t.name}</h3><p class="tense-meaning">${t.meaning}</p>
 <div class="tense-structure-highlight"><span>THE BASIC STRUCTURE</span><strong>${t.form}</strong></div>
 <div class="tense-example-highlight"><span>IN CONTEXT</span><p>${t.example}</p></div>
 <details class="tense-more"><summary>Build negatives and questions</summary><div class="tense-more-content"><div><b>Negative</b><p>${t.negative}</p></div><div><b>Question</b><p>${t.question}</p></div></div></details>
 <details class="tense-more"><summary>Understand the choice more deeply</summary><div class="tense-more-content"><div><b>Why speakers use it</b><p>${t.insight}</p></div><div class="tense-note">${t.extra}</div></div></details>`;
 panel.querySelector("#backToForms").addEventListener("click",()=>{panel.classList.add("hidden");panel.setAttribute("aria-hidden","true");document.querySelectorAll(".tense-pick").forEach(b=>b.classList.remove("active"));});
 panel.scrollIntoView({behavior:"smooth",block:"nearest"});
}
if ($("timeTabs")) document.querySelectorAll("[data-time]").forEach(b=>b.addEventListener("click",()=>{document.querySelectorAll("[data-time]").forEach(x=>x.classList.toggle("active",x===b));renderTenseList(b.dataset.time)}));
if ($("tenseList")) renderTenseList("Present");
if ($("compareGrid")) {
 $("compareGrid").innerHTML=comparisons.map((c,i)=>`<button class="compare-card compare-button" data-comparison="${i}"><span class="ref-label">COMPARISON ${String(i+1).padStart(2,"0")}</span><h3>${c[0]}</h3><p>${c[1]}</p><p>${c[2]}</p><span class="compare-open">Open comparison <b>→</b></span></button>`).join("");
 document.querySelectorAll(".compare-button").forEach(b=>b.onclick=()=>{const c=comparisons[Number(b.dataset.comparison)];const panel=$("comparisonDetail");panel.classList.remove("hidden");panel.innerHTML=`<div class="detail-top"><span class="pill">LET'S COMPARE</span><button class="close-detail" aria-label="Close comparison">×</button></div><h3>${c[0]}</h3><div class="compare-columns"><div><span class="ref-label">FORM A</span><p>${c[1]}</p></div><div><span class="ref-label">FORM B</span><p>${c[2]}</p></div></div><div class="page-note"><strong>What changes?</strong><p>${c[3]}</p></div><div class="mini-check"><strong>Think it through</strong><p>Which form would you choose if you wanted to emphasize ${c[3].toLowerCase()}</p><button class="btn secondary" id="showCompareHint">Show the key idea</button><p class="hidden" id="compareHint">${c[3]}</p></div>`;panel.scrollIntoView({behavior:"smooth",block:"start"});panel.querySelector(".close-detail").onclick=()=>panel.classList.add("hidden");panel.querySelector("#showCompareHint").onclick=()=>{panel.querySelector("#compareHint").classList.toggle("hidden")};});
}
function loadScenario(){const cat=$("category").value;const arr=scenarios[cat];scenarioIndex=(scenarioIndex+1)%arr.length;currentScenario=arr[scenarioIndex];$("scenarioCount").textContent=`${cat.toUpperCase()} · ${scenarioIndex+1} OF ${arr.length}`;$("scenarioTitle").textContent=currentScenario[0];$("scenarioContext").textContent=currentScenario[1];$("scenarioGoal").textContent=currentScenario[2];$("scenarioTask").textContent=currentScenario[3];$("followup").textContent=currentScenario[4];$("modelBox").innerHTML=`<strong>Possible model response</strong><p>${currentScenario[5]}</p><p class="note">${currentScenario[6]}</p><p class="small-muted">This is one possible response, not the only correct answer.</p>`;$("modelBox").classList.add("hidden");$("showModel").textContent="Show model response";$("response").value="";$("wordCount").textContent="0";document.querySelectorAll(".checklist input").forEach(x=>x.checked=false);renderScenarioActivity()}
let scenarioMode="respond";
function renderScenarioActivity(){if(!$("scenarioActivity")||!currentScenario)return;const box=$("scenarioActivity");const modes={respond:`<strong>Your task</strong><p>Respond naturally to the situation. Focus on the message first, then review your tense choices.</p>`,roleplay:`<strong>Role-play challenge</strong><p>You are speaking directly to the person in this situation. Start with a natural opening, give the information they need, and ask or answer one follow-up question.</p><p class="small-muted">Try to speak for 45–60 seconds without reading a script.</p>`,detective:`<strong>Tense detective</strong><p>Before answering, identify the time references in the situation. Which events are finished? Which connect to now? Is there a reference point in the past or future?</p><p class="small-muted">Underline the time clues mentally, then explain why your chosen tense fits.</p>`,story:`<strong>Continue the story</strong><p>Use the situation as the opening of a short story. Add what happened before, what was happening at the key moment, and what happens next.</p><p class="small-muted">Aim to use at least three different tense forms naturally.</p>`,repair:`<strong>Grammar repair</strong><p>Write your response, then review it as an editor. Check auxiliary verbs, main verb forms, time reference and consistency. Rewrite one sentence to make its meaning clearer.</p><p class="small-muted">Do not change a sentence just because another tense is possible. Change it only if the intended meaning requires it.</p>`};box.innerHTML=modes[scenarioMode]||modes.respond;}
if($("scenarioModes"))document.querySelectorAll(".scenario-mode").forEach(b=>b.onclick=()=>{scenarioMode=b.dataset.mode;document.querySelectorAll(".scenario-mode").forEach(x=>x.classList.toggle("active",x===b));renderScenarioActivity()});
if ($("newScenario")) { $("newScenario").onclick=loadScenario;$("category").onchange=()=>{scenarioIndex=-1;loadScenario()};$("showModel").onclick=()=>{$("modelBox").classList.toggle("hidden");$("showModel").textContent=$("modelBox").classList.contains("hidden")?"Show model response":"Hide model response"};$("clearResponse").onclick=()=>{$("response").value="";$("wordCount").textContent="0"};$("response").oninput=()=>{$("wordCount").textContent=$("response").value.trim()?$("response").value.trim().split(/\s+/).length:0};loadScenario();}

